from pathlib import Path
import base64,hashlib,json,shutil
root=Path('/home/ubuntu/season-balance-20261102-journey-native-r4');assert root.exists() and not (root/'run').exists()
d=shutil.disk_usage(root);assert d.free>=3*1024**3+8*1024**2 and d.free/d.total>=.05
p=root/'part-002.bin';assert not p.exists();data=base64.b64decode('');assert hashlib.sha256(data).hexdigest()=='3bcedfcaeebf092d79406181701d2a5d043df58727917282b5bc7dd6ac78e9b8';p.write_bytes(data)
print(json.dumps({'name':p.name,'bytes':len(data),'sha256':'3bcedfcaeebf092d79406181701d2a5d043df58727917282b5bc7dd6ac78e9b8','native_started':False}))
